  eH = `Без категории`,
  tH = `Может, дело в увлекательном геймплее или в цепляющей истории. А может, дело в добротных персонажах, в безукоризненном дизайне или в затягивающей сетевой игре. Какой бы ни была причина, победитель в этой номинации мгновенно стал классикой.`,
  nH = `Эта игра не просто маскирует виртуальную реальность под обычную. Она улучшает реальность, используя преимущества виртуальной среды, и расширяет границы виртуального измерения.`,
  rH = `Эта игра — уже не новинка. Далеко позади осталось то время, когда разработчики впервые явили миру своё творение. Как настоящие любящие родители, они не прекращают растить и поддерживать своё дитя. И по сей день в игру добавляется что-то новенькое.`,
  iH = `Есть такие игры, которые не раскроются полностью, если играть в них одному. Может, будет веселее, если вашу спину будет прикрывать друг? Или подставит свою спину под ваш нож — это уж кому как нравится. Так или иначе, если вы собираетесь с друзьями, в этой игре вас ждёт веселье.`,
  aH = `Визуальный стиль не должен стремиться к полной реалистичности и достоверности (хотя сама по себе это благородная цель)... Он описывает уникальный внешний вид и мироощущение.`,
  oH = `Создатели этой игры стоят на передовой творческих экспериментов, свежих перспектив и мозгодробительных сюрпризов. Эта игра восхищала, вдохновляла и развлекала не испытанной ранее новизной.`,
  sH = `Это игра не для слабонервных, она вознаграждает упорство. Она самая сложная из тех, что нам полюбились.`,
  cH = `Этот невоспетый герой заслуживает признания за выдающееся музыкальное сопровождение. Сей саундтрек — само совершенство! `,
  lH = `Иногда просто хочется погрузиться в сюжет с головой, и эта игра производит неизгладимое впечатление. Она захватывает, как любая мыльная опера, и выверена, будто первоклассное ТВ-шоу. Брависсимо! Аплодируем игре, затронувшей душу!`,
  uH = `Эта игра — противоядие от напряжения. Она спокойная, она расслабляющая, она погрузит вас в дзен, а ваши заботы растают без следа.`,
  dH = `Изменить номинацию?`,
  fH = `В каждой категории можно номинировать лишь одну игру, а вы уже выбрали %1$s. Хотите номинировать %2$s взамен?`,
  pH = `Голосовать`,
  mH = `Голос учтён`,
  hH = `Голос отдан`,
  gH = `Изменить выбор?`,
  _H = `В каждой категории можно проголосовать лишь за одну игру, а вы уже выбрали %1$s. Хотите выбрать %2$s взамен?`,
  vH = `Похоже, права вашего аккаунта ограничены. Чтобы предотвратить злоупотребления, мы разрешаем номинировать игры только пользователям, совершившим покупки в Steam на 5 долларов США. %1$s, чтобы узнать больше.`,
  yH = `Похоже, права вашего аккаунта ограничены. Чтобы предотвратить злоупотребления, мы разрешаем голосовать только пользователям, совершившим покупки в Steam на 5 долларов США. %1$s, чтобы узнать больше.`,
