  FH = `Создатели этой игры стоят на передовой творческих экспериментов, свежих перспектив и мозгодробительных сюрпризов. Эта игра восхищала, вдохновляла и развлекала не испытанной ранее новизной.`,
  IH = `Это игра не для слабонервных, она вознаграждает упорство. Она самая сложная из тех, что нам полюбились.`,
  LH = `Этот невоспетый герой заслуживает признания за выдающееся музыкальное сопровождение. Сей саундтрек — само совершенство! `,
  RH = `Иногда просто хочется погрузиться в сюжет с головой, и эта игра производит неизгладимое впечатление. Она захватывает, как любая мыльная опера, и выверена, будто первоклассное ТВ-шоу. Брависсимо! Аплодируем игре, затронувшей душу!`,
  zH = `Эта игра — противоядие от напряжения. Она спокойная, она расслабляющая, она погрузит вас в дзен, а ваши заботы исчезнут без следа.`,
  BH = `Игра года`,
  VH = `Игра года в виртуальной реальности`,
  HH = `Любимое дитя`,
  UH = `Друг познаётся в игре`,
  WH = `Выдающийся визуальный стиль`,
  GH = `Самый инновационный геймплей`,
  KH = `Лучшая игра, которая вам не даётся`,
  qH = `Лучший саундтрек`,
  JH = `Лучшая игра с выдающимся сюжетом`,
  YH = `Устройтесь поудобнее`,
  XH = `Лучшая игра на ходу`,
  ZH = `Может, дело в увлекательном геймплее или в цепляющей истории. А может, дело в добротных персонажах, безукоризненном дизайне или в затягивающей сетевой игре. Какой бы ни была причина, победитель в номинации «Игра года» мгновенно становится классикой.`,
  QH = `Эта игра не просто маскирует виртуальную реальность под обычную. Она улучшает реальность, используя преимущества виртуальной среды, и расширяет границы виртуального измерения.`,
  $H = `Эта игра — уже не новинка. Далеко позади осталось то время, когда разработчики впервые явили миру своё творение. Как настоящие любящие родители, они не прекращают растить и поддерживать своё дитя. И по сей день в игру добавляется что-то новенькое.`,
  eU = `Есть такие игры, которые не раскроются полностью, если играть в них одному. Может, будет веселее, если вашу спину будет прикрывать друг? Или подставит свою спину под ваш нож — это уж кому как нравится. Так или иначе, если вы собираетесь с друзьями, в этой игре вас ждёт веселье.`,
  tU = `Визуальный стиль не должен стремиться к полной реалистичности и достоверности (хотя сама по себе это благородная цель)... Он описывает уникальный внешний вид и мироощущение.`,
  nU = `Создатели этой игры стоят на передовой творческих экспериментов, свежих перспектив и мозгодробительных сюрпризов. Эта игра восхищала, вдохновляла и развлекала не испытанной ранее новизной.`,
  rU = `Это игра не для слабонервных, она вознаграждает упорство. Она самая сложная из тех, что нам полюбились.`,
  iU = `Этот невоспетый герой заслуживает признания за выдающееся музыкальное сопровождение. Сей саундтрек — само совершенство! `,
  aU = `Иногда просто хочется погрузиться в сюжет с головой, и эта игра производит неизгладимое впечатление. Она захватывает, как любая мыльная опера, и выверена, будто первоклассное ТВ-шоу. Брависсимо! Аплодируем игре, затронувшей душу!`,
  oU = `Эта игра — противоядие от напряжения. Она спокойная, она расслабляющая, она погрузит вас в дзен, а ваши заботы исчезнут без следа.`,
  sU = `Эта игра была так хороша, что её хотелось брать с собой... что вы и делали! И, к счастью, её бесконечная играбельность лишь увеличилась на ходу.`,
