  cpe = `Если вы согласитесь, данные о частоте кадров игрового процесса будут храниться без привязки к вашему аккаунту Steam и идентифицироваться по типу устройства, на котором вы играете. Эти данные помогают нам узнать больше о совместимости игр и улучшить работу устройств, на которых установлен Steam.`,
