  jpe = `Данные о частоте кадров на Steam Deck основаны на отчётах за %1$s дн. от пользователей Steam Deck, которые согласились предоставить соответствующую информацию.`,
  Mpe = `Данные о частоте кадров на Steam Deck основаны на отчётах от пользователей Steam Deck, которые согласились предоставить соответствующую информацию.`,
  Npe = `Примечание: данные о варьировании в настоящее время не предоставляются, но мы планируем добавить их во время бета-тестирования. Они позволят увидеть, стабильна ли кадровая частота или сильно колеблется.`,
