  Zpe = `На графике представлена информация от пользователей, согласившихся делиться анонимными данными и играющими в %1$s на %2$s. Каждый столбец показывает процент выборок, соответствующий конкретной частоте кадров.`,
  Qpe = `На графике представлена информация от пользователей, согласившихся делиться анонимными данными и играющими в эту игру на %2$s. Каждый столбец показывает процент выборок, соответствующий конкретной частоте кадров.`,
  $pe = `Подробности`,
  eme = `Включены только данные, собранные при стандартном ограничении частоты кадров на %1$s в %2$s кадр/с. Время простоя и недействительные выборки отфильтровываются. За игровой сеанс собирается несколько выборок.`,
  tme = `Пропуски на графике (например, между %1$s и %2$s кадр/с) могут быть вызваны вертикальной синхронизацией, которая согласовывает частоту кадров игры с частотой обновления экрана, чтобы избежать разрывов изображения. Из-за этого собранные данные могут концентрироваться на отметках %1$s и %2$s кадр/с, даже если средняя частота кадров игры находится между ними. Такое поведение ожидаемо при вертикальной синхронизации — хоть оно и может влиять на распределение кадров, это необязательно будет приводить к заметным подвисаниям.`,
